    /// <summary>
    /// Each mission's own transport item, from the game's quest data (the mission's item variable for its transport:
    /// itm_heroic_transport, heroic_transport, transport_pass, itm_transport), by mission id. Several heroics give an item
    /// with the same name ("Heroic Transport" on Korriban, Tython and Voss), so a transport is used by its item id when the
    /// mission is here; by its name only when it isn't.
    /// </summary>
    internal static class GameTransports
    {
        /// <summary>The mission's transport item id, or 0 when the game data has none for it.</summary>
        public static ulong For(ulong quest)
        {
            ulong item;
            return Items.TryGetValue(quest, out item) ? item : 0UL;
        }

